/*
  G = GOOG - Google
  A = AMZN - Amazon
  F = META - Facebook (Meta)
  A = AAPL - Apple
  M = MSFT - Microsoft
*/
const request = new XMLHttpRequestMocked(); // ${jA(KA.views.design.data.httpRequestNote)}

request.onload = () => {
  const response = JSON.parse(request.response);

  const mappedResponse = {
    date: new Date(response.timestamp).toLocaleDateString('${qo.getLanguage()}', { year: 'numeric', month: 'short', day: 'numeric' }),
    time: new Date(response.timestamp).toLocaleTimeString('${qo.getLanguage()}', { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
  }

  response.stocks.forEach((stock) => {
    mappedResponse[stock.id] = {
      name:      stock.name,
      price:     stock.price,
      variation: stock.change
    };
  })

  setAPIFields(mappedResponse);
}

request.open('GET', 'http://digo.com/api/v1/stocks', true);
request.send();
